<div class="panel"><div class="tabs"><?php foreach (warehouse_tabs() as $key=>$label): ?><a class="btn <?= $tab===$key ? 'primary' : 'secondary' ?>" href="/warehouse-catalog?tab=<?= e($key) ?>"><?= e($label) ?></a><?php endforeach; ?></div><p class="help">Vị trí thuộc một kho và gồm khu, kệ, ô. Lô gắn với sản phẩm, có thể xuất hiện tại nhiều vị trí. Đơn vị là đơn vị cơ sở; bản mẫu chỉ thêm danh mục.</p></div>
<div class="grid-2 catalog-grid"><div class="panel"><h2>Thêm <?= e(warehouse_tabs()[$tab]) ?></h2>
<?php if ($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?>
<form method="POST" action="/warehouse-catalog?tab=<?= e($tab) ?>"><?= csrf_field() ?>
<?php if ($tab==='locations'): ?><div class="form-group"><label for="warehouse_id">Kho</label><select name="warehouse_id" id="warehouse_id" required><?php foreach ($options['warehouses'] as $w): ?><option value="<?= e($w['id']) ?>" <?= (int)($old['warehouse_id'] ?? 0)===(int)$w['id'] ? 'selected' : '' ?>><?= e($w['code'] . ' · ' . $w['name']) ?></option><?php endforeach; ?></select></div><?php endif; ?>
<?php if ($tab==='lots'): ?><div class="form-group"><label for="lot_product">Sản phẩm</label><select name="product_id" id="lot_product" required><?php foreach ($options['products'] as $p): ?><option value="<?= e($p['id']) ?>" <?= (int)($old['product_id'] ?? 0)===(int)$p['id'] ? 'selected' : '' ?>><?= e($p['name']) ?></option><?php endforeach; ?></select></div><?php endif; ?>
<div class="form-group"><label for="code">Mã</label><input name="code" id="code" required maxlength="<?= $tab==='lots' ? 100 : ($tab==='locations' ? 50 : 30) ?>" value="<?= e($old['code'] ?? '') ?>"></div>
<?php if (in_array($tab,['warehouses','units'],true)): ?><div class="form-group"><label for="name">Tên</label><input name="name" id="name" required maxlength="<?= $tab==='units' ? 100 : 150 ?>" value="<?= e($old['name'] ?? '') ?>"></div><?php endif; ?>
<?php if ($tab==='locations'): ?><?php foreach (['zone'=>'Khu','rack'=>'Kệ','bin'=>'Ô'] as $key=>$label): ?><div class="form-group"><label for="<?= $key ?>"><?= $label ?></label><input name="<?= $key ?>" id="<?= $key ?>" maxlength="50" value="<?= e($old[$key] ?? '') ?>"></div><?php endforeach; ?><?php endif; ?>
<?php if ($tab==='lots'): ?><div class="form-group"><label for="expires_on">Hạn sử dụng (bỏ trống nếu không áp dụng)</label><input type="date" name="expires_on" id="expires_on" value="<?= e($old['expires_on'] ?? '') ?>"></div><?php endif; ?><button class="btn primary">Thêm danh mục</button></form></div>
<div class="panel table-scroll"><h2>Danh sách</h2><table class="table"><thead><tr><th>Mã</th><th>Thông tin</th></tr></thead><tbody><?php foreach ($result['items'] as $item): ?><tr><td><strong><?= e($item['code']) ?></strong></td><td><?php if ($tab==='locations'): ?><?= e($item['warehouse_name']) ?><small><?= e($item['zone'] . ' / ' . $item['rack'] . ' / ' . $item['bin']) ?></small><?php elseif ($tab==='lots'): ?><?= e($item['product_name']) ?><small>Hạn dùng: <?= e($item['expires_on'] ?? 'Không áp dụng') ?></small><?php else: ?><?= e($item['name']) ?><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$result['items']): ?><tr><td colspan="2" class="empty">Chưa có dữ liệu.</td></tr><?php endif; ?></tbody></table><?= pagination_links($result,'/warehouse-catalog',['tab'=>$tab]) ?></div></div>
